using System;using System.Reflection;using System.Windows.Forms;class UiTests{static int n;static void Check(bool b,string m){if(!b)throw new Exception(m);n++;}[STAThread]static void Main(){var a=Assembly.LoadFrom("Trainer.exe");using(var f=(Form)Activator.CreateInstance(a.GetType("TrainerWindow"))){Check(f.Text.Contains("1.3"),"version");TabControl t=null;foreach(Control c in f.Controls)if(c is TabControl)t=(TabControl)c;Check(t!=null&&t.TabPages.Count==2,"two tabs");Check(t.TabPages[1].Text.Contains("剧透"),"spoiler tab");var p=t.TabPages[1].Controls[0];Check(p is UserControl,"save panel");Check(p.Controls.Count>=2,"warning and gate");foreach(Control c in p.Controls)if(c is Panel)Check(c.Enabled,"save operations container enabled");Check(t.TabPages[0].Controls.Count>10,"existing UI retained");}Console.WriteLine("PASS "+n+" UI structure assertions");}}
